void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;

    vec4 accum = texture(iChannel0,uv);
    accum.xyz /= accum.a; // Average

    fragColor = vec4(accum.xyz,1.0);
}

