#define PI 3.14159264

//-------------------------------
// Random Number Generator
//-------------------------------
// https://www.shadertoy.com/view/ctj3Wc
uint rng_state;

uint PCGHash()
{
    rng_state = rng_state * 747796405u + 2891336453u;
    uint state = rng_state;
    uint word = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;
    return (word >> 22u) ^ word;
}


// FragCoord and Time To Hash Uint
// Seed must take a different value for each pixel every frame
void  SetSeed( ivec2 fragCoord, int frame )
{
    rng_state = uint(frame);
    rng_state = PCGHash();
    rng_state += uint(fragCoord.x);
    rng_state = PCGHash();
    rng_state += uint(fragCoord.y);
}

float rnd1(){
    return float(PCGHash()) / float(-1u);
}

vec2 rnd2(){
    return vec2(rnd1(),rnd1());
}


//-------------------------------
// SDF
//-------------------------------
float sdBox( vec3 p, vec3 b )
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

float sdSphere(vec3 p, float r){
    return length(p) - r;
}

int materialID;
// 0 : White
// 1 : Red
// 2 : Green
// 3 : Light

float map(vec3 p){

    materialID = 0;

    // Cornel Box
    float dCeiling = sdBox(p - vec3(0.0,1.05,0.0),vec3(1.05,0.05,1.0)); // materialID = 0
    float dWallR = sdBox(p - vec3(1.0,0.0,0.0),vec3(0.05,1.0,1.0)); // materialID = 1
    float dWallL = sdBox(p + vec3(1.0,0.0,0.0),vec3(0.05,1.0,1.0)); // materialID = 2
    float dWallB = sdBox(p - vec3(0.0,0.0,1.0),vec3(1.0,1.0,0.05)); // materialID = 0
    float dFloor = sdBox(p + vec3(0.0,1.05,0.0),vec3(1.05,0.05,1.0)); // materialID = 0
    float dLight = sdBox(p - vec3(0,1.0,0),vec3(0.5,0.05,0.5)); // materialID = 3

    // Sphere
    float dSphere = sdSphere(p + vec3(0.0,0.6,0.0),0.4);

    float d = dCeiling;
    d = min(d, dWallB);
    d = min(d, dFloor);

    if(d > dWallR) materialID = 1; 
    d = min(d, dWallR);

    if(d > dWallL) materialID = 2; 
    d = min(d, dWallL);

    if(d > dLight) materialID = 3; 
    d = min(d, dLight);

    if(d > dSphere) materialID = 4; 
    d = min(d, dSphere);

    return d;
}

vec3 GetNormal(vec3 p){
    vec2 epsiron = vec2(0.001,0.0);
    return normalize(vec3(
        map(p + epsiron.xyy) - map(p - epsiron.xyy),
        map(p + epsiron.yxy) - map(p - epsiron.yxy),
        map(p + epsiron.yyx) - map(p - epsiron.yyx)
    ));
}


//-------------------------------
// Intersection
//-------------------------------
struct IntersectionInfo{
    vec3 position;
    vec3 normal;
    vec3 color;
    vec3 emission;
    float metallic;
    float roughness;
};

struct Ray{
    vec3 origin;
    vec3 direction;
};

bool Intersect(Ray ray, inout IntersectionInfo info){

    // Intersection must be defined as intersection algorithm for "Ray" and "Object(SDF in this case)"
    // It doesn't matter whether you use ray tracing or ray marching.

    // Raymarching
    vec3 pos = ray.origin;
    vec3 dir = ray.direction;

    float d = 0.0;
    for(int i = 0; i < 100; i++){
        d = map(pos);
        if(d < 0.001){
            info.position = pos;
            info.normal = GetNormal(pos);

            if(materialID == 0){
                info.color = vec3(0.8);
                info.emission = vec3(0.0);
                info.metallic = 0.0;
                info.roughness = 1.0;
            }
            if(materialID == 1){
                info.color = vec3(0.8,0.2,0.2);
                info.emission = vec3(0.0);
                info.metallic = 0.0;
                info.roughness = 1.0;
            }
            if(materialID == 2){
                info.color = vec3(0.2,0.8,0.2);
                info.emission = vec3(0.0);
                info.metallic = 0.0;
                info.roughness = 1.0;
            }
            if(materialID == 3){
                info.color = vec3(0.8);
                info.emission = vec3(5.0,5.0,4.0);
                info.metallic = 0.0;
                info.roughness = 1.0;
            }
            if(materialID == 4){
                info.color = vec3(0.8);
                info.emission = vec3(0.0);
                info.metallic = 1.0;
                info.roughness = 0.1;
            }
            return true;
        }
        pos += d * dir;
    }

    return false;
}



// Create Tangent Space Basis From Normal
void TangentBasis(vec3 normal, inout vec3 tangent, inout vec3 binormal){
    vec3 up = vec3(0,1,0);
    if(abs(normal.y) > 0.99) up = vec3(0,0,-1);

    binormal = normalize(cross(normal,up));
    tangent = cross(binormal,normal);
}

