// Lambert BRDF
// Importance Sampling For Lambert BRDF
vec3 CosineSampling(vec2 xi){
    float theta = acos(1.0 - 2.0f * xi.x) * 0.5;
    float phi = 2.0 * PI * xi.y;
    return vec3(sin(theta) * cos(phi),cos(theta),sin(theta) * sin(phi));
}

vec3 EvaluateLambertBRDF(vec3 color){
    return color / PI;
}

// Sample Incident Direction and Evaluate BRDF
// Input
// wo : Outgoing Direction
// color : Surface Color
// xi : 2 Random Number

// Output 
// wi : Incident Direction
// pdf : Probability Density Function
// return : Lambert BRDF
vec3 SampleLambertBRDF(vec3 wo,vec3 color, vec2 xi, inout vec3 wi, inout float pdf){
    wi = CosineSampling(xi);
    pdf = wi.y / PI;
    return EvaluateLambertBRDF(color);
}


// Microfacet BRDF(GGX)
// My Article : https://kinakomoti321.hatenablog.com/entry/2022/01/29/011529
float GGX_D(vec3 wm,float alpha){
	float term1 = wm.x * wm.x / (alpha * alpha) + wm.z * wm.z / (alpha * alpha) + wm.y * wm.y;
	float term2 = PI * alpha * alpha * term1 * term1;
	return 1.0f / term2;
}

float GGX_Lambda(vec3 w, float alpha)
{
	float term = 1.0 + (alpha * alpha * w.x * w.x + alpha * alpha * w.z * w.z) / (w.y * w.y);
	return (-1.0 + sqrt(term)) * 0.5;
}

float GGX_G1(vec3 w,float alpha){
    return 1.0 / (1.0 + GGX_Lambda(w,alpha));
}

float GGX_G2(vec3 wo, vec3 wi, float alpha)
{
	return 1.0 / (1.0 + GGX_Lambda(wo,alpha) + GGX_Lambda(wi,alpha));
}

vec3 Shlick_Fresnel(vec3 F0, vec3 v, vec3 n)
{
	return F0 + (1.0 - F0) * pow(1.0 - dot(v, n), 5.0);
}

// There is some importance sampling in Microfacet BRDF(GGX)

// Walter Sampling
// [Walter, et al. 2007] Microfacet Models for Refraction through Rough Surfaces
// less efficient than other, but simplest.
vec3 WalterSampling(vec2 xi,float alpha){
    float phi = 2.0 * PI * xi.x;
    float theta = atan(alpha * sqrt(xi.y) / (sqrt(1.0 - xi.y)));
    return vec3(sin(theta) * cos(phi),cos(theta),sin(theta) * sin(phi));
}

// Visible Normal Sampling
// [Heitz 2018] Sampling the GGX Distribution of Visible Normals
// Generally, More Efficient than Walter Sampling
// Practically be used
vec3 SampleGGXVNDF(vec3 Ve, float alpha_x, float alpha_y, float U1, float U2)
{
    // Use Y-up
    Ve = Ve.xzy;
    vec3 Vh = normalize(vec3(alpha_x * Ve.x, alpha_y * Ve.y, Ve.z));

    float lensq = Vh.x * Vh.x + Vh.y * Vh.y;
    vec3 T1 = lensq > 0.0 ? vec3(-Vh.y, Vh.x, 0) * inversesqrt(lensq) : vec3(1,0,0);
    vec3 T2 = cross(Vh, T1);

    float r = sqrt(U1);
    float phi = 2.0 * PI * U2;
    float t1 = r * cos(phi);
    float t2 = r * sin(phi);
    float s = 0.5 * (1.0 + Vh.z);
    t2 = (1.0 - s)*sqrt(1.0 - t1*t1) + s*t2;

    vec3 Nh = t1*T1 + t2*T2 + sqrt(max(0.0, 1.0 - t1*t1 - t2*t2))*Vh;

    vec3 Ne = normalize(vec3(alpha_x * Nh.x, alpha_y * Nh.y, max(0.0, Nh.z)));
    Ne = Ne.xzy;
    return Ne;
} 

// Spherical Cap Visible Normal Sampling
// [Dupuy, Benyoub, 2023] Sampling Visible GGX Normals with Spherical Caps
// More Efficient than Heitz's VNDF sampling
// Theoretically, this is equal Heitz's VNDF Sampling
float fma(float a, float b, float c){
    return a * b + c; // can't use fma function in shadertoy
}
vec3 SphereicalCapVNDFSampling(vec2 u, vec3 wi, float alpha_x, float alpha_y)
{
    wi = wi.xzy;
    wi = normalize(vec3(alpha_x * wi.x, alpha_y * wi.y, wi.z));

    float phi = 2.0f * PI * u.x;
    float z = fma((1.0f - u.y), (1.0f + wi.z), -wi.z);
    float sinTheta = sqrt(clamp(1.0f - z * z, 0.0f, 1.0f));
    float x = sinTheta * cos(phi);
    float y = sinTheta * sin(phi);
    vec3 c = vec3(x, y, z);

    vec3 h = c + wi;

    vec3 wo = normalize(vec3(alpha_x * h.x, alpha_y * h.y, h.z));
    wo = wo.xzy;

    return wo;
}

vec3 SampleMicrofacetBRDF(vec3 wo, float roughness, vec3 F0, vec2 xi, inout vec3 wi, inout float pdf)
{
    float alpha = clamp(roughness * roughness, 0.0001, 1.0); // Roughness to alpha (Practically)

    // Half Vector Sampling (Microfacet Normal)
    vec3 wm;
    //wm = WalterSampling(xi,alpha); 
    //wm = SampleGGXVNDF(wo,alpha,alpha,xi.x,xi.y);
    wm = SphereicalCapVNDFSampling(xi, wo, alpha, alpha);
    wi = reflect(-wo,wm);

    if(wi.y < 0.0){
        // Inside Direction must be removed in BRDF (But, use it in BTDF)
        pdf = 1.0;
        return vec3(0.0);
    }

    float D = GGX_D(wm, alpha);
    float G = GGX_G2(wo, wi, alpha);
    vec3 F = Shlick_Fresnel(F0, wo, wm);

    float jacobian = 1.0 / (4.0 * dot(wo,wm));

    // PDF
    // Walter Sampling
    // pdf = D * wm.y * jacobian;

    // Visible Normal Sampling : VNDF Sampling, SphericalCap VNDF Sampling
    float G1 = GGX_G1(wo,alpha);
    float Dv = D * dot(wm,wo) * G1 / wo.y;
    pdf = Dv * jacobian;

    return F * D * G / (4.0 * wo.y * wi.y);
}

//-------------------------------
// Pathtracing 
//-------------------------------

// Convert World Coordinate To Local Coordinate : lx, ly, lz
vec3 WorldToLocal(vec3 v,vec3 lx, vec3 ly,vec3 lz){
    return vec3(dot(v, lx),dot(v,ly),dot(v,lz));
}

// Convert Local Coodinate To World Coordinate
vec3 LocalToWorld(vec3 v, vec3 lx, vec3 ly, vec3 lz)
{
    return vec3(dot(v ,vec3(lx.x,ly.x,lz.x)),dot(v ,vec3(lx.y,ly.y,lz.y)),dot(v ,vec3(lx.z,ly.z,lz.z)));
}

vec3 Pathtrace(Ray firstRay){
    Ray ray = firstRay;

    vec3 LTE = vec3(0.0);
    vec3 throughput = vec3(1.0);

    float rp = 1.0; // Probability for Rossian Roulette

    for(int i = 0; i < 5; i++){

        // Rossian Roullet
        // Probablitity Is Arbitrary [0,1]
        // Practically, Use Maximum of Thoughput. (if throughput is low, the path is low contribution, so not use the path)
        rp = clamp(max(max(throughput.x,throughput.y),throughput.z),0.0,1.0);
        if(rp < rnd1()) break;
        throughput /= rp; // Divide Probablity


        IntersectionInfo info;
        if(!Intersect(ray, info)){
            // No hit
            vec3 skyEmission = vec3(0.0);
            LTE = skyEmission * throughput;
            break;

        }

        if(length(info.emission) > 0.01){
           // Light Hit
           LTE = info.emission * throughput;
           break;
        }


        // Create Tangent Space Bisis
        vec3 normal = info.normal;
        vec3 tangent,binormal;
        TangentBasis(normal,tangent,binormal);

        // Outgoing Direction wo in Tangent Space
        vec3 wo = -ray.direction;
        vec3 local_wo = WorldToLocal(wo,tangent,normal,binormal);

        // Sample Incident Direction(Tangent Sapce) wi, pdf and Evaluate BSDF
        float pdf;
        vec3 local_wi;
        vec3 bsdf;
        if(info.metallic > 0.0){
            bsdf = SampleMicrofacetBRDF(local_wo, info.roughness, info.color,rnd2(),local_wi,pdf);        
        }
        else {
            bsdf = SampleLambertBRDF(local_wo,info.color,rnd2(),local_wi,pdf);
        }
        // Incident Direction in World Space
        vec3 wi = LocalToWorld(local_wi,tangent,normal,binormal);

        // Calculate Attenuation Rate Per One Bounce
        float cosine = dot(info.normal,wi);
        throughput *= bsdf * cosine / pdf; 

        // Next Ray
        ray.direction = wi;
        ray.origin = info.position + 0.02 * ray.direction; 

    }
    return LTE;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    SetSeed(ivec2(fragCoord),iFrame);

    vec2 uv = (fragCoord * 2.0 + rnd2() - iResolution.xy) /iResolution.y;
    vec2 texuv = fragCoord / iResolution.xy;

    // Camera Ray 
    Ray ray;
    ray.origin = vec3(0,0,-4);
    ray.direction = normalize(vec3(uv,3));

    vec3 col;
    col = Pathtrace(ray);

    // Prefreme Resolution Check
    bool resize = texelFetch(iChannel0,ivec2(0),0).x != iResolution.x;

    // Accumulation
    vec4 accumCol = texture(iChannel0,texuv);
    if(resize) accumCol = vec4(col,1.0);
    else accumCol += vec4(col,1.0);

    // Store last resolution
    if(ivec2(fragCoord)==ivec2(0)) {
        accumCol = iResolution.xyxy;
    }

    fragColor = accumCol;
}
